], [$authHeader, "Cookie: $sessionCookie"]);
check('saving a caption with a valid CSRF token succeeds', str_contains($saveCaptionBody, 'class="flash ok"'));
[, $publicBodyWithCaption] = http_get("$baseAdmin/");
