[, $hiddenTrackBody] = http_get("$basePrivate/?track=loose1.jpg", ["Cookie: $revealCookie"]);
check('tracking a hidden item as a revealed viewer counts it', str_contains($hiddenTrackBody, '"ok":true') && str_contains($hiddenTrackBody, '"photoViews":1'));
http_get("$basePrivate/?track=loose2.jpg", ["Cookie: $revealCookie"]);
$sqliteBlob = is_file("$fxPrivate/.gallery-stats.sqlite") ? (string) file_get_contents("$fxPrivate/.gallery-stats.sqlite") : '';
$sqliteWal = is_file("$fxPrivate/.gallery-stats.sqlite-wal") ? (string) file_get_contents("$fxPrivate/.gallery-stats.sqlite-wal") : '';
$jsonBlob = is_file("$fxPrivate/.gallery-stats.php") ? (string) file_get_contents("$fxPrivate/.gallery-stats.php") : '';
check('(setup) a stats store exists', $sqliteBlob !== '' || $jsonBlob !== '');
check('the SQLite stats file (and its WAL) never contains a filename, hidden or not', !str_contains($sqliteBlob . $sqliteWal, 'loose1.jpg') && !str_contains($sqliteBlob . $sqliteWal, 'loose2.jpg'));
check('...and the hidden item\'s count is real and comes back (revealed viewer\'s page badge)', str_contains((string) http_get("$basePrivate/", ["Cookie: $revealCookie"])[1], 'data-photo="loose1.jpg">' . ico('eye') . ' 1<'));
if ($jsonBlob !== '') {
    [$privStatsStatus, $privStatsBody] = http_get("$basePrivate/.gallery-stats.php");
    check('the guarded JSON stats file answers 404 with an empty body when fetched', $privStatsStatus === 404 && $privStatsBody === '');
}
[$revealedImgStatus] = http_get("$basePrivate/?img=loose1.jpg&size=thumb", ["Cookie: $revealCookie"]);
check('?img= serves a hidden item once revealed', $revealedImgStatus === 200);

// A valid admin login counts as revealed too, on the *public* page.
[, , $adminLoginHeaders] = http_get("$basePrivate/?admin", [$adminAuth]);
$adminRevealCookie = extract_cookie_header($adminLoginHeaders);
[, $adminRevealedBody] = http_get("$basePrivate/", ["Cookie: $adminRevealCookie"]);
check('a valid admin login also sets the reveal cookie, unlocking the public page too', str_contains($adminRevealedBody, 'loose1.jpg'));

// The admin tool itself always sees everything, regardless of hiding.
[, $adminGridBody] = http_get("$basePrivate/?admin", [$adminAuth, "Cookie: $sessCookie"]);
check('the admin tool\'s own grid always shows a hidden item, hide flag and all', str_contains($adminGridBody, 'loose1.jpg'));
check('the admin shows an Edited entry in the sidebar, above the folder list, with the not-a-lock explanation, while hidden items exist', str_contains($adminGridBody, 'class="side-hidden edited"') && strpos($adminGridBody, 'class="side-hidden edited"') < strpos($adminGridBody, 'class="admin-folder-nav"') && str_contains($adminGridBody, 'data-tab="hidden"') && str_contains($adminGridBody, "Private isn't locked") && str_contains($adminGridBody, 'by their direct address'));
check('[hover] the admin\'s plain buttons answer a mouse and a press (zero strength, so a button\'s own hover wins), and the filter chips and +N answer too', str_contains($adminGridBody, ':where(button:not(.linklike):not(:disabled):hover, .btn:hover) { filter:brightness(1.14); }') && str_contains($adminGridBody, ':where(button:not(.linklike):not(:disabled):active, .btn:active) { transform:scale(0.97); }') && str_contains($adminGridBody, 'button.secondary:hover:not(:disabled) { background:#3a3a42; color:#fff; }') && str_contains($adminGridBody, '.ed-chip:not([aria-pressed=true]):hover') && str_contains($adminGridBody, '.ed-more:hover'));
check('[tab names] the sidebar says Settings (not Site settings), the folder-level tab is Folder settings, and the Root\'s card on the Edited tab is called Root', str_contains($adminGridBody, 'data-tab="site" class="side-link">Settings</a>') && str_contains($adminGridBody, 'data-tab="settings">Folder settings</a>') && !str_contains($adminGridBody, '>Site settings<') && !str_contains($adminGridBody, 'Main page'));
check('...and the top tabs stay the same four sections (Hidden is not one of them)', (bool) preg_match('#<nav class="admin-tabs".*?</nav>#s', $adminGridBody, $tabNav) && !str_contains($tabNav[0], 'hidden'));
check('...with only the title and Log out in the header (one row); the folder\'s own tabs sit under its heading in the page, not up there', (function ($b) { $p1 = strpos($b, '<h1>Gallery Admin</h1>'); $p3 = strpos($b, 'class="logout-form"'); $pe = strpos($b, '</header>'); $ph = strpos($b, 'id="admin-folder-head"'); $p2 = strpos($b, '<nav class="admin-tabs"'); return $p1 !== false && $p1 < $p3 && substr_count(substr($b, 0, $p3), '<header') === 1 && $pe > $p3 && $ph > $pe && $p2 > $ph && !str_contains(substr($b, 0, $pe), '<nav class="admin-tabs"'); })($adminGridBody));

// Hidden-items summary: three tiers, not a flat list.
[, $hiddenSummaryBody] = http_get("$basePrivate/?admin&hidden=1", [$adminAuth, "Cookie: $sessCookie"]);
check('the Edited tab has a card for the entirely-hidden folder (a "hidden folder" tag) with a one-line account of what opening it would do, and no separate Private folders list any more', (bool) preg_match('#<section class="ed-folder" data-path="Paris">.*?hidden folder.*?<p class="ed-pf muted">[^<]*public when opened#s', $hiddenSummaryBody) && !str_contains($hiddenSummaryBody, 'id="pv-overview"') && !str_contains($hiddenSummaryBody, 'class="pv-grp"'));
check('the Edited tab lists the individually-hidden photo under its (public) folder as a thumbnail with a working lock that shows it in its folder', (bool) preg_match('#<a class="pv-img" href="\?find=loose1\.jpg"#', $hiddenSummaryBody) && (bool) preg_match('#<button type="button" class="pv-lock own" data-file="loose1\.jpg" data-bare="loose1\.jpg" data-folder="" data-own="private"#', $hiddenSummaryBody));
check('[edited] a private folder\'s card offers Open folder, Folder settings and Make public… (the question and its counts), and the page has the question and its toast', (bool) preg_match('#<section class="ed-folder" data-path="Paris">.*?<a class="ed-btn" href="\?folder=Paris">Open folder</a> <a class="ed-btn" href="\?admin&amp;folder=Paris\#settings">Folder settings</a> <button type="button" class="ed-btn pv-makepub" data-folder="Paris"#s', $hiddenSummaryBody) && str_contains($hiddenSummaryBody, 'id="pt-modal"') && str_contains($hiddenSummaryBody, 'id="pv-toast"') && !str_contains($hiddenSummaryBody, 'See them in the gallery') && !str_contains($hiddenSummaryBody, 'class="hidden-list"'));

// Aggregate counts exclude hidden items, not just their thumbnails —
// loose1 hidden + Paris hidden leaves only loose2 visible (1 photo).
check('the header photo count excludes hidden items, not just their thumbnails', (bool) preg_match('/<p>1 photo\b/', $afterRevertBody));

// The two password prompts share the throttle mechanism but not its
// lockout state — failing the admin login doesn't lock out ?reveal.
for ($i = 0; $i < 5; $i++) {
    http_get("$basePrivate/?admin", ['Authorization: Basic ' . base64_encode('admin:wrong' . $i)]);
}
[$adminLockedStatus] = http_get("$basePrivate/?admin", [$adminAuth]);
check('5 failed admin attempts lock out the admin login', $adminLockedStatus === 429);
[, $adLockBody, $adLockHd] = http_get("$basePrivate/?admin", [$adminAuth]);
check('[lockout page] the admin lockout is a proper page, not bare text: it says sign-in is paused in its own words, counts the seconds left (and says so in Retry-After),', str_contains($adLockBody, 'Sign-in paused') && str_contains($adLockBody, 'id="lock-secs"') && str_contains($adLockBody, 'wrong access codes') && (bool) preg_grep('~^Retry-After: (\\d+)$~i', array_map('trim', $adLockHd)) && (bool) preg_grep('~^Content-Type: text/html~i', $adLockHd));
[$revealStillWorksStatus] = http_get("$basePrivate/?reveal", [$revealAuth], false);
check('...and the shared sign-in box holds it too (429 for that address, even with the right private-view password), so it can\'t be used to keep guessing the admin password', $revealStillWorksStatus === 429 && http_get("$basePrivate/?reveal")[0] === 200);
[, $rvLockBody] = http_post("$basePrivate/?reveal", ['login_password' => 'wrong'], [], false);
check('[lockout page] the shared sign-in box shows the same page for a locked address, and never a retry of what was typed (the page\'s own try-again is a plain visit)', str_contains($rvLockBody, 'Sign-in paused') && str_contains($rvLockBody, 'location.assign(location.href)') && !str_contains($rvLockBody, '<form'));

// Neither password feature does anything when unset (the default).
[$revealInertStatus] = http_get("$base1/?reveal");
check('?reveal 404s outright when PRIVATE_VIEW_PASSWORD is unset (the default)', $revealInertStatus === 404);

// A bare request (no credentials) is just a visit to the form, so any
// number of them must never lock anyone out.
$bareStatuses = [];
for ($i = 0; $i < 8; $i++) { [$bareStatuses[]] = http_get("$basePrivate/?reveal"); }
check('eight bare ?reveal requests all just get the password form (no lockout from missing credentials)', $bareStatuses === array_fill(0, 8, 200));

// ENABLE_MAP off (the default): ?map is simply ignored, not a crash or a
