$s2Admin = function (array $fields) use ($baseS2, $s2AdminCookie, $s2Csrf) {
    [, $body] = http_post("$baseS2/?admin", $fields + ['csrf_token' => $s2Csrf], ['X-Requested-With: gallery-fetch', "Cookie: $s2AdminCookie"]);
